from pathlib import Path

play_dir = Path("/home/USER/runs/paper/qwen-in-glm-h-u1/frozen/seen-7/play")
all_files = list(play_dir.rglob("*"))

# Count files by extension
dirs = {}
exts = {}

for f in all_files:
    rel = str(f.relative_to(play_dir))
    if "/" in rel:
        key = rel.split("/")[0]
        dirs[key] = dirs.get(key, 0) + 1
    else:
        ext = f.suffix
        exts[ext] = exts.get(ext, 0) + 1

print("Directories:")
for k, v in sorted(dirs.items(), key=lambda x: -x[1])[:10]:
    print(f"  {v} items in {k}")

print("\nFile extensions:")
for k, v in sorted(exts.items(), key=lambda x: -x[1]):
    print(f"  {v} {k}")

